import React, { useEffect, useState } from 'react';
import { View, Text, StyleSheet, TouchableOpacity, FlatList, Alert, SafeAreaView } from 'react-native';
import { fetchWithAuth } from '../lib/api';

export default function ProviderDetail({ route, navigation }) {
  const { providerId } = route.params || {};
  const [provider, setProvider] = useState(null);
  const [error, setError] = useState(false);

  useEffect(() => {
    const loadProvider = async () => {
      try {
        const res = await fetchWithAuth(`/api/providers/${providerId}`);
        const json = await res.json();
        setProvider(json);
      } catch (e) {
        setError(true);
      }
    };
    loadProvider();
  }, [providerId]);

  if (error) return <View style={styles.container}><Text style={styles.message}>Tarjoajaa ei löydy.</Text></View>;
  if (!provider) return <View style={styles.container}><Text style={styles.message}>Ladataan...</Text></View>;

  return (
    <SafeAreaView style={styles.safe}>
      <View style={styles.container}>
        <View style={styles.headerCard}>
          <Text style={styles.name}>{provider.name}</Text>
          <Text style={styles.description}>{provider.description}</Text>
          <TouchableOpacity style={styles.reviewButton} onPress={() => navigation.navigate('ReviewScreen', { targetType: 'provider', targetId: provider.id, targetName: provider.name })}>
            <Text style={styles.buttonText}>Katso arvostelut</Text>
          </TouchableOpacity>
        </View>
        <Text style={styles.section}>Arvostelut</Text>
        <FlatList
          data={provider.reviews || []}
          keyExtractor={(item) => item.id}
          ListEmptyComponent={<Text style={styles.empty}>Ei arvosteluja vielä.</Text>}
          renderItem={({ item }) => (
            <View style={styles.card}>
              <Text style={styles.reviewer}>{item.reviewer}</Text>
              <Text style={styles.rating}>Arvio: {item.rating}/5</Text>
              <Text style={styles.comment}>{item.comment}</Text>
            </View>
          )}
        />
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: '#f4f8fb' },
  container: { flex: 1, padding: 16 },
  headerCard: { backgroundColor: '#fff', borderRadius: 18, padding: 20, borderWidth: 1, borderColor: '#e3eaef', marginBottom: 18 },
  name: { fontSize: 22, fontWeight: '800', marginBottom: 8 },
  description: { color: '#556b7a', lineHeight: 22, marginBottom: 14 },
  reviewButton: { backgroundColor: '#15948b', paddingVertical: 14, borderRadius: 14, alignItems: 'center' },
  buttonText: { color: '#fff', fontWeight: '700' },
  section: { fontSize: 18, fontWeight: '700', marginBottom: 12, color: '#0f2f3d' },
  card: { backgroundColor: '#fff', borderRadius: 14, padding: 16, borderWidth: 1, borderColor: '#e3eaef', marginBottom: 12 },
  reviewer: { fontWeight: '700', marginBottom: 4 },
  rating: { marginBottom: 8, color: '#15948b' },
  comment: { color: '#556b7a' },
  empty: { color: '#777', textAlign: 'center', marginTop: 12 },
  message: { color: '#556b7a', textAlign: 'center', marginTop: 24 }
});
